CollapsedGroup: FC<CollapsedGroupProps> = ({
  stages,
  isStreaming,
  labels,
  className,
  styles: groupStyles,
}) => {
  const {
    executedLabel = 'Executed',
    stepsLabel = () => 'steps',
    failedCountLabel = (n: number) => `${n} failed`,
    runningStepLabel = (current: number, total: number) =>
      `Step ${current} of ${total}`,
    runningAriaLabel = 'Running',
    copyAriaLabel,
    failedAriaLabel,
    attemptLabel,
  } = labels ?? {};

  const [isOpen, setIsOpen] = useState(isStreaming);
  const wasStreamingRef = useRef(isStreaming);
  useEffect(() => {
    if (wasStreamingRef.current && !isStreaming) {
      // The run just finished — collapse to the one-line summary.
      setIsOpen(false);
    }
    wasStreamingRef.current = isStreaming;
  }, [isStreaming]);

  const { colors, panel: panelColors } = groupStyles ?? {};

  const summaryTypography = groupStyles?.typography ?? {
    fontClassName: 'dial-small-text',
  };
  const cssVars = buildCssVars({
    '--cs-cg-label': colors?.labelColor,
    '--cs-cg-label-hover': colors?.labelHoverColor,
    '--cs-cg-steps-count': colors?.stepsCountColor,
    '--cs-cg-done': colors?.doneColor,
    '--cs-cg-failed': colors?.failedColor,
    '--cs-text': panelColors?.text,
    '--cs-row-hover': panelColors?.rowHoverColor,
    '--cs-button-bg': panelColors?.collapsedButtonBg,
    '--cs-stage-text': panelColors?.stageTextColor,
    '--cs-failed-text': panelColors?.failedColor,
    '--cs-tag-text': panelColors?.tagTextColor,
    '--cs-count-text': panelColors?.countTextColor,
    '--cs-duration-text': panelColors?.durationTextColor,
    '--cs-icon-secondary': panelColors?.iconSecondaryColor,
    '--cs-icon-completed': panelColors?.iconCompletedColor,
    '--cs-icon-error': panelColors?.iconErrorColor,
    '--cs-code-bg': panelColors?.codeBg,
    '--cs-code-border': panelColors?.codeBorderColor,
    '--cs-code-text': panelColors?.codeTextColor,
    '--cs-border': panelColors?.borderColor,
  });

  if (stages.length === 0) return null;

  const panelLabels = {
    copyAriaLabel,
    runningAriaLabel,
    failedAriaLabel,
    attemptLabel,
  };

  if (stages.length === 1) {
    return (
      <StagesPanel
        stages={stages}
        isStreaming={isStreaming}
        className={className}
        styles={{ colors: panelColors, typography: groupStyles?.typography }}
        labels={panelLabels}
      />
    );
  }

  const hasFailed = stages.some((s) => s.status === StageStatus.Failed);
  const totalSeconds = calculateStagesDurationSeconds(
    stages.map((stage) => stage.name),
  );
  const totalDurationLabel =
    totalSeconds > 0 ? formatTotalDuration(totalSeconds) : undefined;

  const liveStage = isStreaming ? findLiveStage(stages) : undefined;

  let summary;
  if (isStreaming) {
    const position = liveStage
      ? stagePosition(stages, liveStage)
      : stages.length;
    const liveName = liveStage ? cleanStageName(liveStage.name).name : '';
    summary = (
      <span
        role="status"
        aria-live="polite"
        className="flex min-w-0 items-center gap-2"
      >
        <span className="flex flex-none items-center">
          <Spinner size={14} ariaLabel={runningAriaLabel} />
        </span>
        <span
          className={mergeClasses(
            'flex-none whitespace-nowrap',
            summaryTypography.fontClassName,
            styles.liveName,
          )}
        >
          {runningStepLabel(position, stages.length)}
        </span>
        {liveName && (
          <span
            className={mergeClasses(
              'min-w-0 max-w-[22rem] truncate',
              summaryTypography.fontClassName,
              styles.executedLabel,
            )}
          >
            <EllipsisTooltip text={liveName} />
          </span>
        )}
      </span>
    );
  } else if (hasFailed) {
    const failedCount = stages.filter(
      (s) => s.status === StageStatus.Failed,
    ).length;
    summary = (
      <span className="inline-flex items-center gap-1">
        <span
          className={mergeClasses(
            summaryTypography.fontClassName,
            styles.executedLabel,
          )}
        >
          {executedLabel} {stages.length} {stepsLabel(stages.length)}
        </span>
        <span
          className={mergeClasses(
            summaryTypography.fontClassName,
            styles.failedText,
          )}
        >
          {failedCountLabel(failedCount)}
        </span>
        {totalDurationLabel && (
          <span
            className={mergeClasses(
              summaryTypography.fontClassName,
              styles.stepsCount,
            )}
          >
            {totalDurationLabel}
          </span>
        )}
      </span>
    );
  } else {
    summary = (
      <span className="inline-flex items-center gap-1">
        <IconCheck
          size={DIAL_ICON_SIZE.SM}
          className={styles.doneIcon}
          aria-hidden
          stroke={DIAL_KIT_ICON_STROKE}
        />
        <span
          className={mergeClasses(
            summaryTypography.fontClassName,
            styles.executedLabel,
          )}
        >
          {executedLabel} {stages.length} {stepsLabel(stages.length)}
        </span>
        {totalDurationLabel && (
          <span
            className={mergeClasses(
              summaryTypography.fontClassName,
              styles.stepsCount,
            )}
          >
            {totalDurationLabel}
          </span>
        )}
      </span>
    );
  }

  return (
    <div
      style={cssVars}
      className={mergeClasses(
        'flex w-full flex-col gap-1',
        className,
        CONVERSATION_STAGES_CLASS.group,
      )}
    >
      <LinkButton
        className={mergeClasses(
          styles.toggleButton,
          CONVERSATION_STAGES_CLASS.groupToggle,
        )}
        textClassName="min-w-0"
        onClick={() => setIsOpen((prev) => !prev)}
        aria-expanded={isOpen}
        iconAfter={
          isOpen ? (
            <IconChevronDown
              size={12}
              aria-hidden
              stroke={DIAL_KIT_ICON_STROKE}
            />
          ) : (
            <IconChevronRight
              size={12}
              className="rtl:scale-x-[-1]"
              aria-hidden
              stroke={DIAL_KIT_ICON_STROKE}
            />
          )
        }
        label={summary}
      />
      <div
        className={mergeClasses(
          'grid transition-[grid-template-rows] duration-300 ease-in-out',
          isOpen ? 'grid-rows-[1fr]' : 'grid-rows-[0fr]',
        )}
      >
        <div className="overflow-hidden">
          <StagesPanel
            stages={stages}
            isStreaming={isStreaming}
            styles={{
              colors: panelColors,
              typography: groupStyles?.typography,
            }}
            labels={panelLabels}
            className="pt-1"
          />
        </div>
      </div>
    </div>
  );
}

StagesPanel: FC<StagesPanelProps> = ({
  stages,
  isStreaming,
  className,
  styles: panelStyles,
  labels,
}) => {
  const { colors, typography } = panelStyles ?? {};

  const cssVars = buildCssVars({
    '--cs-text': colors?.text,
    '--cs-row-hover': colors?.rowHoverColor,
    '--cs-button-bg': colors?.collapsedButtonBg,
    '--cs-stage-text': colors?.stageTextColor,
    '--cs-failed-text': colors?.failedColor,
    '--cs-tag-text': colors?.tagTextColor,
    '--cs-count-text': colors?.countTextColor,
    '--cs-duration-text': colors?.durationTextColor,
    '--cs-icon-secondary': colors?.iconSecondaryColor,
    '--cs-icon-completed': colors?.iconCompletedColor,
    '--cs-icon-error': colors?.iconErrorColor,
    '--cs-code-bg': colors?.codeBg,
    '--cs-code-border': colors?.codeBorderColor,
    '--cs-code-text': colors?.codeTextColor,
    '--cs-border': colors?.borderColor,
  });

  const rows = groupStagesByName(stages);

  return (
    <div
      style={cssVars}
      className={mergeClasses(
        'w-full',
        styles.panel,
        className,
        CONVERSATION_STAGES_CLASS.panel,
      )}
    >
      <ul role="list" className="flex w-full flex-col gap-0.5 ps-5">
        {rows.map((row) =>
          row.stage ? (
            <li key={row.key} role="listitem">
              <StageItem
                stage={row.stage}
                isLive={isStreaming && row.stage.status == null}
                typography={typography}
                labels={labels}
              />
            </li>
          ) : (
            <li key={row.key} role="listitem">
              <StageGroupRow
                row={row}
                isLive={
                  isStreaming &&
                  (row.attempts?.some((attempt) => attempt.status == null) ??
                    false)
                }
                typography={typography}
                labels={labels}
              />
            </li>
          ),
        )}
      </ul>
    </div>
  );
}

export interface CollapsedGroupColors {
  /** Color of the toggle button label and icon. */
  labelColor?: string;
  /** Color of the toggle button label and icon on hover. */
  labelHoverColor?: string;
  /** Color of the execution time. */
  stepsCountColor?: string;
  /** Color of the leading check icon in the finished-and-successful summary. */
  doneColor?: string;
  /** Color of the "N failed" text in the failed summary. */
  failedColor?: string;
}

export interface CollapsedGroupLabels {
  /** Label shown before the steps count on the toggle button. Defaults to `'Executed'`. */
  executedLabel?: string;
  /** Returns the pluralized steps label. Defaults to `() => 'steps'`. */
  stepsLabel?: (count: number) => string;
  /** Returns the "N failed" text in the failed summary. Defaults to `(n) => \`${n} failed\``. */
  failedCountLabel?: (failedCount: number) => string;
  /** Returns the "Step X of Y" text in the running summary. Defaults to `(current, total) => \`Step ${current} of ${total}\``. */
  runningStepLabel?: (current: number, total: number) => string;
  /** Accessible label announced for the running summary's spinner. Defaults to `'Running'`. */
  runningAriaLabel?: string;
  /** Accessible label for the copy button on each stage's content. Defaults to `'Copy'`. */
  copyAriaLabel?: string;
  /** Visually-hidden label announced alongside a failed stage's icon. Defaults to `'Failed'`. */
  failedAriaLabel?: string;
  /** Returns the label for a single attempt inside a collapsed `×N` group. Defaults to `(n) => \`Attempt ${n}\``. */
  attemptLabel?: (attemptNumber: number) => string;
}

export interface CollapsedGroupProps {
  /** Ordered list of stages to display. */
  stages: Stage[];
  /** When true, expands to a live progress line; collapses to a summary once streaming ends. */
  isStreaming: boolean;
  /** User-visible strings for the toggle button. */
  labels?: CollapsedGroupLabels;
  /** Extra class name(s) merged onto the outer wrapper. */
  className?: string;
  /** Color and typography overrides applied as CSS custom properties. */
  styles?: CollapsedGroupStyles;
}

export interface CollapsedGroupStyles {
  /** Color overrides applied as CSS custom properties. */
  colors?: CollapsedGroupColors;
  /** Typography for the toggle button label. */
  typography?: CollapsedGroupTypography;
  /** Color overrides forwarded to the inner `StagesPanel`. */
  panel?: StagesPanelColors;
}

export interface CollapsedGroupTypography {
  /** CSS utility class applied to the toggle button label. Defaults to `'dial-small-text'`. */
  fontClassName?: string;
}

export interface StagesPanelColors {
  /** General text color. Defaults to `--text-primary`. */
  text?: string;
  /** Background tint on row hover. Defaults to `--bg-layer-sunken`. */
  rowHoverColor?: string;
  /** Text color of each stage name. Defaults to `--text-secondary`. */
  stageTextColor?: string;
  /** Text and icon color for a failed stage. Defaults to `--text-warning`. */
  failedColor?: string;
  /** Background color of the collapse button. Defaults to transparent. */
  collapsedButtonBg?: string;
  /** Text color of stage tag labels. Defaults to `--text-tertiary`. */
  tagTextColor?: string;
  /** Text color of the attempt count badge (e.g. `×N`). Defaults to `--text-tertiary`. */
  countTextColor?: string;
  /** Text color of the total-duration label. Defaults to `--text-tertiary`. */
  durationTextColor?: string;
  /** Color of secondary (non-status) icons. Defaults to `--text-secondary` at 70% opacity. */
  iconSecondaryColor?: string;
  /** Color of the completed-check icon. Defaults to `--text-tertiary`. */
  iconCompletedColor?: string;
  /** Color of the error/exception icon. Defaults to `--text-warning`. */
  iconErrorColor?: string;
  /** Background color of fenced code blocks and inline code. Defaults to `--bg-layer-raised`. */
  codeBg?: string;
  /** Border color of fenced code blocks and inline code. Defaults to `--stroke-secondary`. */
  codeBorderColor?: string;
  /** Text color inside code blocks. Defaults to `--text-primary`. */
  codeTextColor?: string;
  /** Border color used for table cells and blockquotes. Defaults to `--stroke-secondary`. */
  borderColor?: string;
}

export interface StagesPanelLabels {
  /** Accessible label for the copy button on each stage's content. Defaults to `'Copy'`. */
  copyAriaLabel?: string;
  /** Accessible label announced for a running stage's spinner. Defaults to `'Running'`. */
  runningAriaLabel?: string;
  /** Visually-hidden label announced alongside a failed stage's icon. Defaults to `'Failed'`. */
  failedAriaLabel?: string;
  /** Label for a single attempt given its 1-based number. Defaults to `(n) => \`Attempt ${n}\``. */
  attemptLabel?: (attemptNumber: number) => string;
}

export interface StagesPanelProps {
  /** Ordered list of stages to display. */
  stages: Stage[];
  /** When `true`, every stage with `status: null` shows a live spinner. */
  isStreaming: boolean;
  /** Extra class name(s) merged onto the outer wrapper. */
  className?: string;
  /** Color and typography overrides applied as CSS custom properties. */
  styles?: StagesPanelStyles;
  /** User-visible strings. */
  labels?: StagesPanelLabels;
}

export interface StagesPanelStyles {
  /** Color overrides applied as CSS custom properties. */
  colors?: StagesPanelColors;
  /** Typography applied to the stage name and expanded content. */
  typography?: StageTypography;
}

export interface StageTypography {
  /** CSS utility class applied to the stage/step name. Defaults to `'dial-small-text'`. */
  fontClassName?: string;
  /** CSS utility class applied to expanded content text elements (paragraphs, lists, blockquotes, links, table cells). Defaults to `'dial-tiny-text'`. */
  contentClassName?: string;
  /** CSS utility class applied to `<strong>` (bold markdown) inside expanded content. Falls back to `contentClassName`, then `'dial-tiny-text'`. */
  strongClassName?: string;
  /** CSS utility class applied to every heading level (`h1`–`h6`) inside expanded content. Defaults to `'dial-small-semi-text'`. */
  headingClassName?: string;
  /** CSS utility class applied to inline code elements. Defaults to `'dial-code-text rounded-md'`. */
  codeClassName?: string;
  /** CSS utility class applied to fenced code blocks (`<pre>`). Defaults to `'dial-code-text'`. */
  codeBlockClassName?: string;
  /** CSS utility class applied to count badges (e.g. `×N` collapsed group). Defaults to `'dial-tiny-text'`. */
  countFontClassName?: string;
  /** CSS utility class applied to a stage's tag label. Defaults to `'dial-tiny-lead-text'`, which uppercases the label itself. */
  tagClassName?: string;
}

CONVERSATION_STAGES_CLASS = {
  /** The stages panel root, which carries the themed CSS variables. */
  panel: 'dial-conversation-stages-panel',
  /** The root of a `CollapsedGroup`, wrapping its summary line and the panel. */
  group: 'dial-conversation-stages-group',
  /** The summary line of a `CollapsedGroup`, which expands and collapses it. */
  groupToggle: 'dial-conversation-stages-group-toggle',
} as const

